import{_ as a,a as i,b as o,c as l}from"./chunks/holybro_sik_longrange_include2.EaWtX9Az.js";import{_ as r,o as t,c as n,al as d}from"./chunks/framework.7vp1BMOE.js";const y=JSON.parse('{"title":"Holybro SiK Telemetry Radio - Long Range","description":"","frontmatter":{},"headers":[],"relativePath":"uk/telemetry/holybro_sik_longrange.md","filePath":"uk/telemetry/holybro_sik_longrange.md"}'),s={name:"uk/telemetry/holybro_sik_longrange.md"};function h(c,e,p,u,m,g){return t(),n("div",null,[...e[0]||(e[0]=[d('<h1 id="holybro-sik-telemetry-radio-long-range" tabindex="-1">Holybro SiK Telemetry Radio - Long Range <a class="header-anchor" href="#holybro-sik-telemetry-radio-long-range" aria-label="Permalink to &quot;Holybro SiK Telemetry Radio - Long Range&quot;">​</a></h1><p>This Holybro SiK Long Range Telemetry Radio is a small, light, and inexpensive open-source radio platform with an extended range (~20km) compared to the standard model.</p><p>This radio is plug-and-play, ready for all Pixhawk Standard and other similar flight controllers, providing the easiest way to set up a telemetry connection between your controller and a ground station. It uses open-source firmware that has been specially designed to work well with MAVLink packets and to be integrated with PX4, ArduPilot, Mission Planner and QGroundControl.</p><p>The radios are available in 915 MHz or 433 MHz versions. Please purchase the model that is appropriate for your country/region.</p><p><img src="'+a+'" alt="Sik Telemetry Radio - Long Range"></p><h2 id="де-купити" tabindex="-1">Де купити <a class="header-anchor" href="#де-купити" aria-label="Permalink to &quot;Де купити&quot;">​</a></h2><ul><li><a href="https://holybro.com/collections/telemetry-radios/products/sik-telemetry-radio-1w" target="_blank" rel="noreferrer">Holybro SiK Telemetry Radio - Long Range</a></li></ul><h2 id="функціі" tabindex="-1">Функції <a class="header-anchor" href="#функціі" aria-label="Permalink to &quot;Функції&quot;">​</a></h2><ul><li>1W maximum RF output and up to 20km range (compared to 100mW/300m for the short range version).</li><li>Open-source SIK firmware</li><li>Plug-n-play for Pixhawk Standard Flight Controllers</li><li>The Easiest way to connect your controller and Ground Station</li><li>Можливість взаємозамінності радіо на повітрі та на землі</li><li>6-позиційний роз&#39;єм JST-GH</li></ul><h2 id="специфікація" tabindex="-1">Специфікація <a class="header-anchor" href="#специфікація" aria-label="Permalink to &quot;Специфікація&quot;">​</a></h2><ul><li>1 W maximum output power (adjustable) -117 dBm receive sensitivity</li><li>РП-SMA роз&#39;єм</li><li>Двосторонній повний дуплексний зв&#39;язок через адаптивний інтерфейс TDM UART</li><li>Прозоре послідовне посилання</li><li>Формування протоколу MAVLink</li><li>Частотно-перестроювана розподілена спектральна модуляція (FHSS) Налаштований цикл роботи</li><li>Корекція помилок виправляє до 25% помилок бітів Відкрите програмне забезпечення SIK</li><li>Configurable through Mission Planner &amp; APM Planner</li><li>FT230X USB на BASIC UART IC</li><li>USB Type C connector</li><li>XT30 power connector for 7~28V DC input</li></ul><h2 id="стан-індикатора-світлодіодів" tabindex="-1">Стан індикатора світлодіодів <a class="header-anchor" href="#стан-індикатора-світлодіодів" aria-label="Permalink to &quot;Стан індикатора світлодіодів&quot;">​</a></h2><p>The radios have four status LEDs. The USB <code>RX</code> and <code>TX</code> LEDs indicate the status of reception and transmission of the USB port. The <code>RADIO</code> and <code>ACT</code> two LED lights indicate the status of the RF circuit.</p><ul><li>USB-TX LED (orange): <ul><li>Blinking: USB port has data transmission</li><li>Off: USB port has no data transmission</li></ul></li><li>USB-RX LED (orange): <ul><li>Blinking: USB port has data reception</li><li>Off: USB port has no data reception</li></ul></li><li>Radio LED (Green) <ul><li>Blinking: Searching for another radio</li><li>Solid: Link is established with another radio</li></ul></li><li>ACT LED (Red) <ul><li>Flashing: Transmitting data</li><li>Solid: In firmware update mode</li></ul></li></ul><p><img src="'+i+'" alt="Holybro SiK LongRange LED Indicators"></p><h2 id="підключення-до-політного-контролера" tabindex="-1">Підключення до Політного Контролера <a class="header-anchor" href="#підключення-до-політного-контролера" aria-label="Permalink to &quot;Підключення до Політного Контролера&quot;">​</a></h2><p>Supply the power (7~28V) to the radio via the XT30 connector. Use the 6-pin JST-GH connector that comes with the radio to connect the radio to your flight controller&#39;s <code>TELEM1</code> port.</p><p>Note that <code>TELEM2</code> can also be used, but you may need to <a href="./../peripherals/mavlink_peripherals">configure the telemetry port</a> on some flight controllers.</p><h2 id="підключення-до-пк-або-наземноі-станціі" tabindex="-1">Підключення до ПК або Наземної станції <a class="header-anchor" href="#підключення-до-пк-або-наземноі-станціі" aria-label="Permalink to &quot;Підключення до ПК або Наземної станції&quot;">​</a></h2><p>First, power the module with a 7~28V DC source. Then, connect the radio to your Windows PC or Ground Station using a Type-C USB cable.</p><p>The necessary drivers should be installed automatically, and the radio will appear as a new “USB Serial Port” in the Windows Device Manager under Ports (COM &amp; LPT). The Mission Planner&#39;s COM Port selection drop-down should also include the newly added COM port.</p><h2 id="packages-include" tabindex="-1">Packages Include <a class="header-anchor" href="#packages-include" aria-label="Permalink to &quot;Packages Include&quot;">​</a></h2><h3 id="single-radio" tabindex="-1">Single Radio <a class="header-anchor" href="#single-radio" aria-label="Permalink to &quot;Single Radio&quot;">​</a></h3><ul><li>1W Radio modules with antennas (1)</li><li>High-gain omnidirectional antenna (1)</li><li>Male Type-C to male Type-C USB cable (1)</li><li>Male XT30 to female XT30 adapter cable (1)</li><li>Male XT30 to female XT60 adapter cable (1)</li><li>JST-GH-6P to JST-GH-6P cable (1) (for Pixhawk Standard FC)</li><li>Rubber damping grommet (3)</li></ul><p><img src="'+o+'" alt="Sik Telemetry Radio - LongRange Package1"></p><h3 id="pair-radios" tabindex="-1">Pair Radios <a class="header-anchor" href="#pair-radios" aria-label="Permalink to &quot;Pair Radios&quot;">​</a></h3><ul><li>1W Radio modules with antennas (2)</li><li>High-gain omnidirectional antenna (2)</li><li>Male Type-C to male Type-C USB cable (1)</li><li>Male XT30 to female XT30 adapter cable (1)</li><li>Male XT30 to female XT60 adapter cable (1)</li><li>JST-GH-6P to JST-GH-6P cable (1) (for Pixhawk Standard FC)</li><li>Rubber damping grommet (3)</li></ul><p><img src="'+l+'" alt="Sik Telemetry Radio - LongRange Package2"></p>',28)])])}const S=r(s,[["render",h]]);export{y as __pageData,S as default};
